function sieve(n){ if(n<2) return []; var s=new Array(n+1).fill(true); s[0]=s[1]=false;
  for(var i=2;i*i<=n;i++){ if(s[i]){ for(var j=i*i;j<=n;j+=i) s[j]=false; } }
  var out=[]; for(var i=2;i<=n;i++) if(s[i]) out.push(i); return out; }
var EXPORTS={sieve:sieve};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SieveForgePure = EXPORTS; }
